const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envFilePath = path.join(__dirname, '.env.test');

// Helper function to read DATABASE_URL from .env.test
function getDatabaseUrl() {
  if (!fs.existsSync(envFilePath)) {
    return null;
  }

  try {
    const content = fs.readFileSync(envFilePath, 'utf-8');
    const lines = content.split(/\r?\n/);
    for (const line of lines) {
      const trimmed = line.trim();
      // Skip comments and empty lines
      if (trimmed && !trimmed.startsWith('#')) {
        const index = trimmed.indexOf('=');
        if (index !== -1) {
          const key = trimmed.substring(0, index).trim();
          const value = trimmed.substring(index + 1).trim();
          if (key === 'DATABASE_URL') {
            return value;
          }
        }
      }
    }
  } catch (error) {
    console.error('Error reading .env.test file:', error.message);
  }
  return null;
}

function runMigrations() {
  // Read DATABASE_URL from .env.test
  const databaseUrl = getDatabaseUrl();
  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Log successful connection (without printing the actual connection string/credentials)
  console.log('Successfully connected to database.');

  // Ensure the migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Migrations directory './migrations' does not exist.`);
    process.exit(1);
  }

  try {
    // Read all files from the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them alphabetically
    const sqlFiles = files
      .filter(file => file.toLowerCase().endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    // Log each filename in order
    sqlFiles.forEach(file => {
      console.log(file);
    });
  } catch (error) {
    console.error('Error reading migrations:', error.message);
    process.exit(1);
  }
}

runMigrations();

